class Solution:
 def widthOfBinaryTree(self,root):
  if not root:return 0
  q=[(root,0)];best=0
  while q:
   base=q[0][1];best=max(best,q[-1][1]-base+1);nxt=[]
   for node,i in q:
    i-=base
    if node.left:nxt.append((node.left,2*i))
    if node.right:nxt.append((node.right,2*i+1))
   q=nxt
  return best

class Solution:
 def checkPossibility(self,nums):
  changed=0
  for i in range(1,len(nums)):
   if nums[i]<nums[i-1]:
    changed+=1
    if changed>1:return False
    if i<2 or nums[i]>=nums[i-2]:nums[i-1]=nums[i]
    else:nums[i]=nums[i-1]
  return True

class Solution:
 def constructArray(self,n,k):
  out=[];lo=1;hi=k+1
  while lo<=hi:
   out.append(lo);lo+=1
   if lo<=hi:out.append(hi);hi-=1
  out.extend(range(k+2,n+1))
  return out

class Solution:
 def trimBST(self,root,low,high):
  if root is None:return None
  if root.val<low:return self.trimBST(root.right,low,high)
  if root.val>high:return self.trimBST(root.left,low,high)
  root.left=self.trimBST(root.left,low,high);root.right=self.trimBST(root.right,low,high);return root

class Solution:
 def findSecondMinimumValue(self,root):
  if root is None:return -1
  first=root.val;second=float('inf')
  def dfs(n):
   nonlocal second
   if n is None:return
   if first<n.val:second=min(second,n.val);return
