  dfs(root);return -1 if second==float('inf') else second

class Solution:
 def findLengthOfLCIS(self,nums):
  if not nums:return 0
  best=cur=1
  for i in range(1,len(nums)):
   cur=cur+1 if nums[i]>nums[i-1] else 1;best=max(best,cur)
  return best

class Solution:
 def validPalindrome(self,s):
  def pal(l,r):
   while l<r:
    if s[l]!=s[r]:return False
    l+=1;r-=1
   return True
  l=0;r=len(s)-1
  while l<r:
   if s[l]!=s[r]:return pal(l+1,r) or pal(l,r-1)
   l+=1;r-=1
  return True

class Solution:
 def calPoints(self,operations):
  scores=[]
  for op in operations:
   if op=='C':scores.pop()
   elif op=='D':scores.append(2*scores[-1])
   elif op=='+':scores.append(scores[-1]+scores[-2])
   else:scores.append(int(op))
  return sum(scores)

class Solution:
 def findRedundantConnection(self,edges):
  parent=list(range(len(edges)+1));rank=[0]*len(parent)
  def find(x):
   while parent[x]!=x:parent[x]=parent[parent[x]];x=parent[x]
   return x
  for a,b in edges:
   x=find(a);y=find(b)
   if x==y:return [a,b]
   if rank[x]<rank[y]:x,y=y,x
   parent[y]=x
   if rank[x]==rank[y]:rank[x]+=1
  return []

class Solution:
 def longestUnivaluePath(self,root):
  self.best=0
  def dfs(n):
   if n is None:return 0
   l=dfs(n.left);r=dfs(n.right);a=b=0
   if n.left and n.left.val==n.val:a=l+1
   if n.right and n.right.val==n.val:b=r+1
   self.best=max(self.best,a+b);return max(a,b)
  dfs(root);return self.best
